{% assign sorted_fields = model.SortMappedFieldsbyFieldPosition %}

<table class="pdc-mapped-fields">
  <colgroup>
    <col class="col-content">
    <col class="col-actions">
  </colgroup>
  <tbody>
    {% if sorted_fields.size > 0 %}
      {% for field in sorted_fields %}
        {% assign is_complete = true %}
        {% unless field.pdc_field_position and field.fluxx_field and field.pdc_field and field.pdc_application_field_instructions %}
          {% assign is_complete = false %}
        {% endunless %}

        <tr class="field-row">
          <td class="content-cell">
            <table class="inner-table">
              <tr class="main-row">
                <td class="position">
                  {% if field.pdc_field_position %}
                    <strong>{{ field.pdc_field_position }}</strong>
                  {% else %}
                    <span class="empty">—</span>
                  {% endif %}
                </td>
                <td class="status">
                  {% if is_complete %}
                    <span class="complete">✓</span>
                  {% else %}
                    <span class="incomplete">⚠</span>
                  {% endif %}
                </td>
                <td class="instructions-preview">
                  <div class="instructions-label">Instructions</div>
                  <div class="instructions-text">
                    {% if field.pdc_application_field_instructions %}
                      {% if field.pdc_application_field_instructions.size > 250 %}
                        {{ field.pdc_application_field_instructions | truncate: 250, "..." }}
                      {% else %}
                        {{ field.pdc_application_field_instructions }}
                      {% endif %}
                    {% else %}
                      <em>No instructions provided</em>
                    {% endif %}
                  </div>
                </td>
              </tr>
              <tr class="detail-row">
                <td colspan="3">
                  <div class="field-details">
                    <div class="field-item">
                      <span class="field-label">Fluxx Field:</span>
                      {% if field.fluxx_field %}
                        <span class="field-value">{{ field.fluxx_field }}</span>
                      {% else %}
                        <span class="field-value empty">Not mapped</span>
                      {% endif %}
                    </div>
                    <div class="field-item">
                      <span class="field-label">PDC Field:</span>
                      {% if field.pdc_field %}
                        <span class="field-value">{{ field.pdc_field }}</span>
                      {% else %}
                        <span class="field-value empty">Not set</span>
                      {% endif %}
                    </div>
                  </div>
                </td>
              </tr>
            </table>
          </td>
          <td class="actions">
            <a href="/machine_models/{{ field.id }}" 
               class="new-detail  action-btn view"
               title="View" 
               data-insert="after">View</a>
          </td>
        </tr>
      {% endfor %}
    {% else %}
      <tr>
        <td class="no-data" colspan="2">No mapped fields found</td>
      </tr>
    {% endif %}
  </tbody>
</table>

<style>
  /* Outer table */
  .pdc-mapped-fields {
    width: 100%;
    max-width: 493px;
    border-collapse: collapse;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    table-layout: fixed;
  }

  /* Column definitions */
  .pdc-mapped-fields .col-content {
    width: calc(100% - 50px);
  }

  .pdc-mapped-fields .col-actions {
    width: 50px;
  }

  /* Outer table cells */
  .pdc-mapped-fields .field-row {
    border-top: 2px solid #d0d0d0;
    border-bottom: 2px solid #d0d0d0;
  }

  .pdc-mapped-fields .content-cell {
    vertical-align: top;
    padding-top: 12px;
  }

  /* Inner table */
  .pdc-mapped-fields .inner-table {
    width: 100%;
    border-collapse: collapse;
  }

  /* Main row styling */
  .pdc-mapped-fields .main-row {
    background: #f0f4f8;
  }

  .pdc-mapped-fields .main-row td {
    padding-right: 6px;
    padding-left: 6px;
    vertical-align: top;
    padding-top: 8px;
    margin-top: 8px;
  }

  /* Position column */
  .pdc-mapped-fields .position {
    width: 30px;
    text-align: center;
    font-size: 16px;
    font-weight: bold;
    color: #2c3e50;
  }

  .pdc-mapped-fields .position .empty {
    color: #ccc;
    font-weight: normal;
  }

  /* Status column */
  .pdc-mapped-fields .status {
    width: 30px;
    text-align: center;
    font-size: 16px;
  }

  .pdc-mapped-fields .status .complete {
    color: #28a745;
  }

  .pdc-mapped-fields .status .incomplete {
    color: #ffc107;
  }

  /* Instructions column */
  .pdc-mapped-fields .instructions-preview {
    padding-left: 8px;
    padding-right: 8px;
  }

  .pdc-mapped-fields .instructions-label {
    font-size: 10px;
    text-transform: uppercase;
    color: #666;
    margin-bottom: 2px;
    font-weight: 600;
  }

  .pdc-mapped-fields .instructions-text {
    font-size: 12px;
    color: #495057;
    line-height: 1.3;
    word-wrap: break-word;
  }

  .pdc-mapped-fields .instructions-text em {
    color: #999;
    font-style: italic;
  }

  /* Detail row styling */
  .pdc-mapped-fields .detail-row {
    background: white;
  }

  .pdc-mapped-fields .field-details {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding-left: 12px;
    padding-right: 12px;
  }

  .pdc-mapped-fields .field-item {
    display: flex;
    align-items: baseline;
  }

  .pdc-mapped-fields .field-label {
    font-weight: 600;
    color: #495057;
    margin-right: 6px;
    font-size: 11px;
    min-width: 70px;
  }

  .pdc-mapped-fields .field-value {
    color: #212529;
    font-size: 12px;
    word-break: break-word;
  }

  .pdc-mapped-fields .field-value.empty {
    color: #999;
    font-style: italic;
  }

  /* Actions column */
  .pdc-mapped-fields .actions {
    padding-left: 2px;
    padding-right: 2px;
    vertical-align: top;
    border-left: 1px solid #d0d0d0;
  }

  .pdc-mapped-fields .action-btn {
    display: block;
    padding: 3px 4px;
    margin-bottom: 2px;
    border-radius: 2px;
    text-decoration: none;
    font-size: 11px;
    font-weight: 500;
    text-align: center;
    transition: opacity 0.2s;
  }

  .pdc-mapped-fields .action-btn:first-child {
    margin-top: 8px; /* Match the padding of main-row td */
  }

  .pdc-mapped-fields .action-btn.view {
    background: #17a2b8;
    color: white;
  }

  .pdc-mapped-fields .action-btn.edit {
    background: #6c757d;
    color: white;
  }

  .pdc-mapped-fields .action-btn.delete {
    background: #dc3545;
    color: white;
  }

  .pdc-mapped-fields .action-btn:hover {
    opacity: 0.8;
  }

  /* No data styling */
  .pdc-mapped-fields .no-data {
    text-align: center;
    padding: 40px;
    color: #666;
    font-size: 14px;
  }
</style>

{% assign pdc_preview = model.grant_or_request_id."PDC_Get_Data_Preview_For_Proposal" %}

<div class="pdc-data-preview">

  <table class="pdc-fields-table">
    <thead>
      <tr>
        <th>Field Name</th>
        <th>Value</th>
      </tr>
    </thead>
    <tbody>
      {% for field in pdc_preview.display_fields %}
      <tr class="{% unless field.has_value %}no-value{% endunless %}">
        <td>{{ field.field_name }}</td>
        <td>
          {% if field.has_value %}
            {{ field.value }}
          {% else %}
            <em>No data</em>
          {% endif %}
        </td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <style>
    .pdc-data-preview {
      margin: 20px 0;
    }
    .pdc-fields-table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 15px;
    }
    .pdc-fields-table th {
      background-color: #f0f0f0;
      padding: 10px;
      text-align: left;
      border-bottom: 2px solid #ddd;
    }
    .pdc-fields-table td {
      padding: 8px;
      border-bottom: 1px solid #eee;
    }
    .pdc-fields-table tbody tr:nth-child(even) {
      background-color: #f8f8f8;
    }
    .pdc-fields-table tr.no-value td {
      color: #999;
    }
    .summary {
      background-color: #f9f9f9;
      padding: 10px;
      border-radius: 4px;
      margin: 10px 0;
    }
  </style>
</div>
